echo "== SoT.base =="; cat 02_bases/SoT.base | head -60; echo; echo "== bookmark paths: exist now? =="; python3 - <<'EOF'
import json,os
d=json.load(open('.obsidian/bookmarks.json'))
def walk(items):
    for i in items:
        if i.get('type')=='group': yield from walk(i.get('items',[]))
        else: yield i
for i in walk(d['items']):
    p=i.get('path')
    if p and ('MoC' in p or 'SoT' in p or '100_zettelkasten' in p):
        base=os.path.basename(p)
        print(('OK ' if os.path.exists(p) else 'MISSING '), p, '| in zk:', os.path.exists('30_Library/100_zettelkasten/'+base))
EOF
echo "== other bases with folder filters =="; grep -nE "folder|inFolder" 02_bases/*.base | cut -c1-160 | head -20; echo "== notebook navigator =="; ls .obsidian/plugins | grep -i navigator; grep -oE "\"(shortcuts|folderNotes|pinned)[^}]{0,300}" .obsidian/plugins/notebook-navigator/data.json 2>/dev/null | head -5
